from typing import List, Tuple

def dependencies_valid(nodes: list[str], edges: list[Tuple[str, str]]) -> bool:
    """
    Returns True if the dependency graph defined by nodes and edges is valid.

    A valid graph must satisfy:
    1. All node names in 'nodes' are unique.
    2. Every edge in 'edges' has both endpoints present in 'nodes'.
    3. The graph is acyclic (no cycles).

    Empty input lists are considered valid.
    """
    # Handle empty inputs
    if not nodes or not edges:
        return True

    # Check for duplicate nodes
    if len(nodes) != len(set(nodes)):
        return False

    # Build a set of valid nodes for quick lookup
    valid_nodes = set(nodes)

    # Check every edge: both endpoints must exist in the valid_nodes set
    for u, v in edges:
        if u not in valid_nodes or v not in valid_nodes:
            return False

    # Check for cycles using DFS
    visited = set()
    rec_stack = set()

    def has_cycle(node: str) -> bool:
        visited.add(node)
        rec_stack.add(node)

        for neighbor in nodes:
            if neighbor == node:
                continue
            if neighbor not in valid_nodes:
                continue

            if neighbor not in visited:
                if has_cycle(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True

        rec_stack.remove(node)
        return False

    # Check if any node in the graph is part of a cycle
    for node in nodes:
        if node in valid_nodes:
            if has_cycle(node):
                return False

    return True

